nta.declaration:
// The mic, a reply generating and a chat switch, in time (dictation.ts, chatDraft.ts, DefaultChatScreen.svelte), 2026-10-22.
// The player records (up to 120 s), stops; the clip goes to POST /api/stt (server/node/stt.cjs: a model load up to 180 s, then up to
// 60 s per clip); the words come back late, maybe after the player opened another chat while a reply generates; a reply may be
// retried (an empty stream) or resumed. A phone that changes network can lose the request: no answer ever comes.
// FIX=0: the code before (the words go into the open chat's box, the retry clears the box, the page waits for ever for /api/stt).
// FIX=1: the code after (tagged words go to their chat, the retry leaves the box, the page gives up after STT_LIMIT s).
// Generated: sed 's/FIX = 1;/FIX = 0;/' mic_template.xml > mic_fix0.xml, and mic_fix1.xml is a copy. Time unit: seconds.
const int FIX = 1;
const int REC_CAP = 120;     // dictation.ts MAX_SECONDS
const int LOAD_MAX = 180;    // stt.cjs loadTimeoutMs
const int STT_MAX = 60;      // stt.cjs timeoutMs
const int STT_LIMIT = 300;   // dictation.ts CLIENT_LIMIT_MS / 1000: past the server's own worst case (load + one clip)
const int GEN_MIN = 7;       // measured: a reply's first word after 7.5 s
const int GEN_MAX = 120;
clock x;                     // the mic
clock g;                     // the reply
clock p;                     // the player: at least a second between two taps (else a run of endless switches in no time)
int[0,1] open = 0;           // the open chat
int[0,1] tag = 0;            // the chat a dictation started in
bool box = false;            // the box holds unsent words (of the open chat, after FIX)
bool draft[2] = {false, false};   // stored drafts (FIX=1)
bool genOn = false;
bool leak = false;           // words landed in a chat they were not spoken for
bool lost = false;           // unsent words were wiped
bool late = false;           // a dictation came back after a switch (the scenario is reachable)

void deliver() {
    if (FIX == 1 && tag != open) { draft[tag] = true; late = true; }
    else { if (tag != open) { leak = true; late = true; } box = true; }
}
void switchChat() {
    if (FIX == 1) { draft[open] = box; open = 1 - open; box = draft[open]; draft[open] = false; }
    else { open = 1 - open; }
}
